function Get-Sha256Hex([byte[]]$Bytes) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace("-", "").ToLowerInvariant() }
    finally { $sha.Dispose() }
}
function Count-Occurrences([string]$Text,[string]$Needle) {
    $count=0; $pos=0
    while ($true) {
        $i=$Text.IndexOf($Needle,$pos,[StringComparison]::Ordinal)
        if ($i -lt 0) { break }
        $count++; $pos=$i+$Needle.Length
    }
    return $count
}
function Find-JsStringEnd([string]$Text,[int]$Start) {
    if ($Start -ge $Text.Length) { throw "문자열 시작 위치가 잘못되었습니다." }
    $quote=$Text[$Start]
    if ($quote -ne '"' -and $quote -ne "'" -and $quote -ne [char]96) { throw "locale 값이 문자열 literal이 아닙니다." }
    for ($i=$Start+1;$i -lt $Text.Length;$i++) {
        if ($Text[$i] -eq $quote) {
            $slashes=0; $j=$i-1
            while ($j -ge $Start -and $Text[$j] -eq '\') { $slashes++; $j-- }
            if (($slashes % 2) -eq 0) { return $i }
        }
    }
    throw "locale 문자열 끝을 찾지 못했습니다."
}
function Replace-LocaleValue([string]$Text,[string]$Key,[string]$NewLiteral) {
    $needle='"'+$Key+'":'
    $count=Count-Occurrences $Text $needle
    if ($count -ne 1) { throw "locale key '$Key'를 정확히 하나 찾지 못했습니다. count=$count" }
    $keyPos=$Text.IndexOf($needle,[StringComparison]::Ordinal)
    $start=$keyPos+$needle.Length
    while ($start -lt $Text.Length -and [char]::IsWhiteSpace($Text[$start])) { $start++ }
    $end=Find-JsStringEnd $Text $start
    return $Text.Substring(0,$start)+$NewLiteral+$Text.Substring($end+1)
}

Write-Host "HackHub 비공식 한국어 개선 패치 v1.0.0"
Write-Host "지원되는 순정 app.asar인지 확인합니다..."
if (-not (Test-Path -LiteralPath $AsarPath)) {
    throw "app.asar를 찾지 못했습니다. 이 스크립트를 Hackhub\resources 폴더에 넣어 주세요."
}

$actualSize=(Get-Item -LiteralPath $AsarPath).Length
$actualSha=(Get-FileHash -LiteralPath $AsarPath -Algorithm SHA256).Hash.ToLowerInvariant()
if ($actualSize -ne $ExpectedAsarSize -or $actualSha -ne $ExpectedAsarSha256) {
    throw @"
지원되지 않는 app.asar입니다.

지원 SHA256: $ExpectedAsarSha256
현재 SHA256: $actualSha

게임이 업데이트되었거나 이미 패치된 파일일 수 있습니다.
Steam에서 파일 무결성 검사를 하여 순정 파일로 복구한 뒤 다시 실행하세요.
"@
}

if (-not (Test-Path -LiteralPath $BackupPath)) {
    Write-Host "원본 백업 생성: app.asar.original.bak"
    Copy-Item -LiteralPath $AsarPath -Destination $BackupPath
} else {
    $backupSha=(Get-FileHash -LiteralPath $BackupPath -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($backupSha -ne $ExpectedAsarSha256) {
        throw "기존 app.asar.original.bak이 지원 원본과 다릅니다. 안전을 위해 중단합니다."
    }
    Write-Host "기존 원본 백업 유지: app.asar.original.bak"
}

if (Test-Path -LiteralPath $TempPath) { Remove-Item -LiteralPath $TempPath -Force }

$srcFs=$null
try {
    $utf8=New-Object System.Text.UTF8Encoding($false)
    $srcFs=[System.IO.File]::Open($AsarPath,[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,[System.IO.FileShare]::Read)

    [byte[]]$preamble=New-Object byte[] 16
    if ($srcFs.Read($preamble,0,16) -ne 16) { throw "ASAR preamble을 읽지 못했습니다." }
    $headerPickleSize=[BitConverter]::ToUInt32($preamble,4)
    $jsonLength=[BitConverter]::ToUInt32($preamble,12)
    $jsonStart=16
    [Int64]$payloadStart=8+[Int64]$headerPickleSize

    [byte[]]$headerBytes=New-Object byte[] $jsonLength
    $srcFs.Position=$jsonStart
    if ($srcFs.Read($headerBytes,0,$headerBytes.Length) -ne $headerBytes.Length) { throw "ASAR JSON header를 읽지 못했습니다." }
    $headerText=$utf8.GetString($headerBytes)

    $metaPattern='"size":(?<size>\d+),"offset":"'+$KnownIndexOffset+'","integrity":\{"algorithm":"SHA256","hash":"(?<hash>[0-9a-f]{64})","blockSize":4194304,"blocks":\[(?<blocks>[^\]]*)\]\}'
    $metaMatches=[regex]::Matches($headerText,$metaPattern)
    if ($metaMatches.Count -ne 1) { throw "dist/assets/index.js 메타데이터를 찾지 못했습니다. 지원 게임 버전인지 확인하세요." }
    $meta=$metaMatches[0]
    [Int64]$currentIndexSize=[Int64]::Parse($meta.Groups['size'].Value)
    [Int64]$indexAbsoluteOffset=$payloadStart+[Int64]$KnownIndexOffset

    [byte[]]$indexBytes=New-Object byte[] $currentIndexSize
    $srcFs.Position=$indexAbsoluteOffset
    $readTotal=0
    while ($readTotal -lt $indexBytes.Length) {
        $n=$srcFs.Read($indexBytes,$readTotal,$indexBytes.Length-$readTotal)
        if ($n -le 0) { throw "index.js를 완전히 읽지 못했습니다." }
        $readTotal+=$n
    }

    $text=$utf8.GetString($indexBytes).TrimEnd([char[]]@([char]0x20))
    $koStartMarker="c5a={"; $koEndMarker="},u5a="
    $koStart=$text.IndexOf($koStartMarker,[StringComparison]::Ordinal)
    if ($koStart -lt 0) { throw "한국어 locale 시작점을 찾지 못했습니다." }
    $koEnd=$text.IndexOf($koEndMarker,$koStart,[StringComparison]::Ordinal)
    if ($koEnd -lt 0) { throw "한국어 locale 끝점을 찾지 못했습니다." }
    $koEnd+=1

    $before=$text.Substring(0,$koStart)
    $koText=$text.Substring($koStart,$koEnd-$koStart)
    $after=$text.Substring($koEnd)

    $fragmentChanged=0
    foreach ($p in $FragmentPatches) {
        $oldText=$utf8.GetString([Convert]::FromBase64String($p.Old))
        $newText=$utf8.GetString([Convert]::FromBase64String($p.New))
        $oldCount=Count-Occurrences $koText $oldText
        if ($oldCount -ne 1) { throw "초기 패치 항목 '$($p.K)'을 정확히 찾지 못했습니다. count=$oldCount" }
        $koText=$koText.Replace($oldText,$newText)
        $fragmentChanged++
    }

    # Historical v5 cleanup that was applied globally to the Korean locale.
    $usageTypoCount=Count-Occurrences $koText "사사용법"
    if ($usageTypoCount -gt 0) { $koText=$koText.Replace("사사용법","사용법") }

    $localeChanged=0
    foreach ($p in $LocalePatches) {
        $newText=$utf8.GetString([Convert]::FromBase64String($p.New))
        $escaped=$newText.Replace('\','\\').Replace('"','\"').Replace("`r",'\r').Replace("`n",'\n').Replace("`t",'\t')
        $newLiteral='"'+$escaped+'"'
        $koText=Replace-LocaleValue $koText $p.K $newLiteral
        $localeChanged++
    }

    $text=$before+$koText+$after
    $rawChanged=0
    foreach ($rp in $RawPatches) {
        $oldText=$utf8.GetString([Convert]::FromBase64String($rp.Old))
        $newText=$utf8.GetString([Convert]::FromBase64String($rp.New))
        $rawCount=Count-Occurrences $text $oldText
        if ($rawCount -ne 1) { throw "UI 문자열을 정확히 하나 찾지 못했습니다. count=$rawCount" }
        $text=$text.Replace($oldText,$newText)
        $rawChanged++
    }

    [byte[]]$newIndex=$utf8.GetBytes($text)
    [Int64]$delta=[Int64]$newIndex.Length-$currentIndexSize
    Write-Host "index.js: $currentIndexSize -> $($newIndex.Length) bytes (delta $delta)"

    $newHash=Get-Sha256Hex $newIndex
    $newBlocks=@()
    for ($offset=0;$offset -lt $newIndex.Length;$offset+=$BlockSize) {
        $len=[Math]::Min($BlockSize,$newIndex.Length-$offset)
        [byte[]]$block=New-Object byte[] $len
        [Array]::Copy($newIndex,$offset,$block,0,$len)
        $newBlocks+=(Get-Sha256Hex $block)
    }
    $blockJson=($newBlocks | ForEach-Object { '"'+$_+'"' }) -join ','

    $offsetPattern='"offset":"(\d+)"'
    $offsetEvaluator=[System.Text.RegularExpressions.MatchEvaluator]{
        param($m)
        [Int64]$n=[Int64]::Parse($m.Groups[1].Value)
        if ($n -gt [Int64]$KnownIndexOffset) { $n+=$delta }
        return '"offset":"'+$n.ToString()+'"'
    }
    $headerShifted=[regex]::Replace($headerText,$offsetPattern,$offsetEvaluator)

    $newMeta='"size":'+$newIndex.Length+',"offset":"'+$KnownIndexOffset+'","integrity":{"algorithm":"SHA256","hash":"'+$newHash+'","blockSize":4194304,"blocks":['+$blockJson+']}'
    if ((Count-Occurrences $headerShifted $meta.Value) -ne 1) { throw "index.js 메타데이터가 header에서 유일하지 않습니다." }
    $newHeaderText=$headerShifted.Replace($meta.Value,$newMeta)
    [byte[]]$newHeader=$utf8.GetBytes($newHeaderText)
    if ($newHeader.Length -ne $jsonLength) { throw "ASAR header 길이가 달라졌습니다. 안전을 위해 중단합니다." }

    $dstFs=[System.IO.File]::Open($TempPath,[System.IO.FileMode]::CreateNew,[System.IO.FileAccess]::ReadWrite,[System.IO.FileShare]::None)
    try {
        $dstFs.Write($preamble,0,$preamble.Length)
        $dstFs.Write($newHeader,0,$newHeader.Length)
        [Int64]$paddingLen=$payloadStart-16-$jsonLength
        if ($paddingLen -lt 0) { throw "ASAR header 계산이 올바르지 않습니다." }
        if ($paddingLen -gt 0) {
            [byte[]]$padding=New-Object byte[] $paddingLen
            $srcFs.Position=16+$jsonLength
            if ($srcFs.Read($padding,0,$padding.Length) -ne $padding.Length) { throw "header padding을 읽지 못했습니다." }
            $dstFs.Write($padding,0,$padding.Length)
        }

        $srcFs.Position=$payloadStart
        [Int64]$remaining=[Int64]$KnownIndexOffset
        [byte[]]$copyBuffer=New-Object byte[] 8388608
        while ($remaining -gt 0) {
            $want=[int][Math]::Min([Int64]$copyBuffer.Length,$remaining)
            $n=$srcFs.Read($copyBuffer,0,$want)
            if ($n -le 0) { throw "index.js 이전 payload 복사 중 예상치 못한 EOF입니다." }
            $dstFs.Write($copyBuffer,0,$n)
            $remaining-=$n
        }

        $dstFs.Write($newIndex,0,$newIndex.Length)
        $srcFs.Position=$indexAbsoluteOffset+$currentIndexSize
        while (($n=$srcFs.Read($copyBuffer,0,$copyBuffer.Length)) -gt 0) { $dstFs.Write($copyBuffer,0,$n) }
        $dstFs.Flush()

        $expectedLength=$srcFs.Length+$delta
        if ($dstFs.Length -ne $expectedLength) { throw "재구성된 ASAR 크기가 예상과 다릅니다." }
    } finally { if ($dstFs) { $dstFs.Dispose() } }

    $verifyFs=[System.IO.File]::OpenRead($TempPath)
    try {
        [byte[]]$verifyIndex=New-Object byte[] $newIndex.Length
        $verifyFs.Position=$indexAbsoluteOffset
        $got=0
        while ($got -lt $verifyIndex.Length) {
            $n=$verifyFs.Read($verifyIndex,$got,$verifyIndex.Length-$got)
            if ($n -le 0) { throw "재구성된 index.js 검증 중 EOF입니다." }
            $got+=$n
        }
        if ((Get-Sha256Hex $verifyIndex) -ne $newHash) { throw "재구성된 index.js integrity 검증에 실패했습니다." }
    } finally { $verifyFs.Dispose() }

    $srcFs.Dispose(); $srcFs=$null
    Remove-Item -LiteralPath $AsarPath -Force
    Move-Item -LiteralPath $TempPath -Destination $AsarPath

    Write-Host ""
    Write-Host "패치 완료!" -ForegroundColor Green
    Write-Host "초기 번역 패치: $fragmentChanged 항목"
    Write-Host "후속 정밀교정: $localeChanged 항목"
    if ($usageTypoCount -gt 0) { Write-Host "오타 정리: $usageTypoCount 항목" }
    Write-Host "별도 UI 문자열: $rawChanged 항목"
    Write-Host "원본 백업: app.asar.original.bak"
    Write-Host "게임을 실행해 한국어 번역을 확인하세요."
}
catch {
    Write-Host ""
    Write-Host "패치 실패: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host "검증 완료 전에는 기존 app.asar를 교체하지 않습니다."
    if (Test-Path -LiteralPath $TempPath) { Remove-Item -LiteralPath $TempPath -Force -ErrorAction SilentlyContinue }
    throw
}
finally { if ($srcFs) { $srcFs.Dispose() } }
